const response = $input.item.json;
let mermaidCode = '';
if (response.content && Array.isArray(response.content)) {
  for (const block of response.content) {
    if (block.type === 'text' && block.text) {
      mermaidCode = block.text.trim()
        .replace(/^```mermaid\n?/i, '')
        .replace(/^```\n?/i, '')
        .replace(/\n?```$/i, '')
        .trim();
      break;
    }
  }
}
if (!mermaidCode.toLowerCase().startsWith('graph')) {
  mermaidCode = 'graph TD\n' + mermaidCode;
}
return [{ json: { mermaidCode, tokens_used: response.usage } }];

const mermaidCode = $input.item.json.mermaidCode;
const base64Code = Buffer.from(mermaidCode, 'utf8').toString('base64');
const urlSafeBase64 = base64Code.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: {
  mermaidCode,
  encodedCode: urlSafeBase64,
  pngUrl: `https://mermaid.ink/img/${urlSafeBase64}?type=png&bgColor=white`,
  svgUrl: `https://mermaid.ink/svg/${urlSafeBase64}`,
  tokens_used: $input.item.json.tokens_used
} }];
